import { MeshPhysicalNodeMaterial, MeshBasicNodeMaterial } from 'three/webgpu';
import { uv, vec2, mix, color, smoothstep } from 'three/tsl';
import { gsap } from 'gsap';

function makeSlabGeometry(THREE, w, h, depth) {
  const shape = new THREE.Shape();
  const hw = w / 2;
  const hh = h / 2;
  shape.moveTo(-hw, -hh);
  shape.lineTo(hw, -hh);
  shape.lineTo(hw, hh);
  shape.lineTo(-hw, hh);
  shape.lineTo(-hw, -hh);
  const geo = new THREE.ExtrudeGeometry(shape, {
    depth,
    bevelEnabled: true,
    bevelThickness: 0.04,
    bevelSize: 0.04,
    bevelSegments: 2,
    curveSegments: 4,
  });
  geo.translate(0, 0, -depth / 2);
  return geo;
}

function makeCellGradientNode() {
  // 135deg diagonal engineered gradient with a hard-stop machined sheen band at 40%
  const t = uv().x.add(uv().y).mul(0.5);
  const base = mix(color('#101017'), color('#1a1a22'), t);
  const band = smoothstep(0.37, 0.4, t).sub(smoothstep(0.4, 0.43, t));
  return base.add(band.mul(0.06));
}

export default function createNode(config, ctx) {
  const THREE = ctx.THREE;
  const group = new THREE.Group();
  group.name = 'bento-metrics-grid';

  const colors = (config.intent && config.intent.visualSpec && config.intent.visualSpec.colors) || {};
  const accent = colors.accent || '#ff2a38';
  const paper = colors.paper || '#e8ecf2';
  const gradientStops = colors.gradientStops || [
    { at: 0, hex: '#101017' },
    { at: 1, hex: '#1a1a22' },
  ];

  const items = config.textContent ?? config.intent?.visualSpec?.textContent ?? [];

  const captionItem = items.find((i) => i.role === 'caption') || items[0];
  const valueLargeItem = items.find((i) => i.role === 'valueLarge') || items[1];
  const dominantLabelItem = items[2];
  const value1Item = items[3];
  const label1Item = items[4];
  const value2Item = items[5];
  const label2Item = items[6];

  const disposables = [];
  const timelines = [];

  // ---------- BACKDROP (fills the frustum; no flat-void regions) ----------
  const backdropGeo = new THREE.PlaneGeometry(24, 14);
  const backdropMat = new MeshBasicNodeMaterial();
  const stop0 = color(gradientStops[0].hex);
  const stop1 = color(gradientStops[gradientStops.length - 1].hex);
  backdropMat.colorNode = mix(stop0, stop1, uv().y);
  const backdrop = new THREE.Mesh(backdropGeo, backdropMat);
  backdrop.position.set(0, 0, -2.5);
  group.add(backdrop);
  disposables.push(backdropGeo, backdropMat);

  // ---------- CONTACT SHADOW (grounds the grid) ----------
  const shadowGeo = new THREE.PlaneGeometry(6.8, 4.6);
  const shadowMat = new MeshBasicNodeMaterial();
  shadowMat.transparent = true;
  const d = uv().sub(vec2(0.5, 0.5)).length();
  shadowMat.colorNode = color('#000000');
  shadowMat.opacityNode = smoothstep(0.5, 0.05, d).mul(0.5);
  const shadowPlane = new THREE.Mesh(shadowGeo, shadowMat);
  shadowPlane.position.set(0, -0.15, -1.0);
  group.add(shadowPlane);
  disposables.push(shadowGeo, shadowMat);

  // ---------- LOCAL LIGHTS (rim carries accent hue, plus soft chamfer fill) ----------
  const rimLight = new THREE.DirectionalLight(new THREE.Color(accent), 0.6);
  rimLight.position.set(2.5, -1.5, 3.0);
  group.add(rimLight);

  const chamferLight = new THREE.DirectionalLight(0xffffff, 0.5);
  chamferLight.position.set(-2.0, 3.0, 4.0);
  group.add(chamferLight);

  // ---------- CELL BUILDER ----------
  const cellDepth = 0.06;
  const cellGroups = [];

  function buildCell({ w, h, x, y, isDominant, valueText, valueFontSize, labelText }) {
    const cellGroup = new THREE.Group();
    cellGroup.position.set(x, y, 0);

    const slabGeo = makeSlabGeometry(THREE, w, h, cellDepth);
    const slabMat = new MeshPhysicalNodeMaterial();
    slabMat.colorNode = makeCellGradientNode();
    slabMat.roughness = 0.5;
    slabMat.metalness = 0.45;
    slabMat.clearcoat = 0.18;
    slabMat.clearcoatRoughness = 0.35;
    const slab = new THREE.Mesh(slabGeo, slabMat);
    cellGroup.add(slab);
    disposables.push(slabGeo, slabMat);

    const innerHalfW = w / 2 - 0.5;
    const innerHalfH = h / 2 - 0.5;

    // accent tick bar — unlit, guaranteed-visible flat red, the single accent per cell
    const tickW = isDominant ? 0.5 : 0.4;
    const tickGeo = new THREE.BoxGeometry(tickW, 0.06, 0.03);
    const tickMat = new MeshBasicNodeMaterial();
    tickMat.colorNode = color(accent);
    const tick = new THREE.Mesh(tickGeo, tickMat);
    tick.position.set(-innerHalfW + tickW / 2, innerHalfH - 0.08, cellDepth / 2 + 0.03);
    cellGroup.add(tick);
    disposables.push(tickGeo, tickMat);

    // value text (Lora, per spec em-height mapping fontSizePx -> ~fontSizePx/200 world units)
    const valueNode = ctx.fontAtlas.createText(valueText, {
      fontSize: valueFontSize,
      color: paper,
      align: 'left',
      letterSpacingPx: -valueFontSize * 0.005,
    });
    const valueY = isDominant ? 0.25 : innerHalfH - 0.42;
    valueNode.position.set(-innerHalfW, valueY, cellDepth / 2 + 0.04);
    cellGroup.add(valueNode);

    // label text (JetBrains Mono, caption weight)
    const labelNode = ctx.fontAtlas.createText(labelText, {
      fontSize: 18,
      color: '#aab0ba',
      align: 'left',
      letterSpacingPx: 18 * 0.08,
    });
    const valueHeightApprox = (valueFontSize / 200) * 1.05;
    labelNode.position.set(-innerHalfW, valueY - valueHeightApprox - 0.15, cellDepth / 2 + 0.04);
    cellGroup.add(labelNode);

    group.add(cellGroup);
    cellGroups.push(cellGroup);
    return cellGroup;
  }

  buildCell({
    w: 3.25,
    h: 3.5,
    x: -1.125,
    y: 0,
    isDominant: true,
    valueText: valueLargeItem ? valueLargeItem.text : '0.002 mm',
    valueFontSize: 124,
    labelText: dominantLabelItem ? dominantLabelItem.text : 'Case tolerance, CNC pass',
  });

  buildCell({
    w: 2.0,
    h: 1.625,
    x: 1.75,
    y: 0.9375,
    isDominant: false,
    valueText: value1Item ? value1Item.text : '38 h',
    valueFontSize: 68,
    labelText: label1Item ? label1Item.text : 'Power reserve, NA-01',
  });

  buildCell({
    w: 2.0,
    h: 1.625,
    x: 1.75,
    y: -0.9375,
    isDominant: false,
    valueText: value2Item ? value2Item.text : '214',
    valueFontSize: 68,
    labelText: label2Item ? label2Item.text : 'Components per calibre',
  });

  // ---------- HEADER CAPTION ----------
  const headerText = ctx.fontAtlas.createText(
    captionItem ? captionItem.text : 'ATELIER METRICS / Q2 2026',
    {
      fontSize: 18,
      color: paper,
      align: 'left',
      letterSpacingPx: 18 * 0.12,
    }
  );
  headerText.position.set(-2.75, 2.25, 0.02);
  group.add(headerText);

  // ---------- ENTRANCE ANIMATION (stagger-cards / fade-up, dominant first) ----------
  cellGroups.forEach((cg) => {
    cg.scale.set(0.96, 0.96, 0.96);
    cg.position.y -= 0.2;
  });
  headerText.scale.set(0.98, 0.98, 0.98);

  const entranceTl = gsap.timeline();
  cellGroups.forEach((cg, i) => {
    entranceTl.to(
      cg.position,
      { y: cg.position.y + 0.2, duration: 0.5, ease: 'power2.out' },
      i * 0.08
    );
    entranceTl.to(
      cg.scale,
      { x: 1, y: 1, z: 1, duration: 0.7, ease: 'power3.out' },
      i * 0.08
    );
  });
  entranceTl.to(
    headerText.scale,
    { x: 1, y: 1, z: 1, duration: 0.5, ease: 'power2.out' },
    0
  );
  timelines.push(entranceTl);

  // ---------- IDLE MOTION (single slow breathing transform, <=2%) ----------
  const idleTl = gsap.timeline({ repeat: -1, yoyo: true, delay: 1.2 });
  idleTl.to(group.scale, {
    x: 1.015,
    y: 1.015,
    z: 1.015,
    duration: 4.0,
    ease: 'sine.inOut',
  });
  timelines.push(idleTl);

  // ---------- HOVER INTERACTIONS (press-down / weighted-settle on dominant cell) ----------
  const dominantCell = cellGroups[0];
  group.userData.handlers = {
    onPointerOver: () => {
      gsap.to(dominantCell.scale, {
        x: 0.97,
        y: 0.97,
        z: 0.97,
        duration: 0.12,
        ease: 'back.out(2)',
      });
    },
    onPointerOut: () => {
      gsap.timeline()
        .set(dominantCell.scale, { x: 1.04, y: 1.04, z: 1.04 })
        .to(dominantCell.scale, {
          x: 1,
          y: 1,
          z: 1,
          duration: 0.9,
          ease: 'power4.out',
        });
    },
  };

  // ---------- CLEANUP ----------
  group.userData.cleanup = () => {
    timelines.forEach((tl) => tl.kill());
    gsap.killTweensOf(dominantCell.scale);
    disposables.forEach((d) => {
      if (d && typeof d.dispose === 'function') d.dispose();
    });
    group.traverse((child) => {
      if (child.geometry && !disposables.includes(child.geometry)) {
        child.geometry.dispose();
      }
      if (child.material) {
        const mats = Array.isArray(child.material) ? child.material : [child.material];
        mats.forEach((m) => {
          if (m && !disposables.includes(m)) {
            if (m.map) m.map.dispose();
            m.dispose();
          }
        });
      }
    });
  };

  return group;
}
